const MAX_SUBTITLE_WORDS = 10;
const MAX_RELEVANT_FILES = 12;
const capSubtitleWords = (text: string): string => {
  const words = text.trim().split(/\s+/);
  return words.length <= MAX_SUBTITLE_WORDS
    ? text
    : `${words.slice(0, MAX_SUBTITLE_WORDS).join(' ')}…`;
};

const mergeRelevantFiles = (...groups: Array<string[] | undefined>): string[] =>
  Array.from(
    new Set(groups.flatMap((group) => group ?? []).filter(Boolean)),
  ).slice(0, MAX_RELEVANT_FILES);
export const DEFAULT_LEASE_TTL_MS = 20 * 60 * 1000;
export const SCAFFOLD_LEASE_TTL_MS = 30 * 60 * 1000;

export interface SessionStoreClock {
  now(): number;
}

const SYSTEM_CLOCK: SessionStoreClock = { now: () => Date.now() };

export interface ProposeArgs {
  guidance?: GuidanceDocument[];
  sessionId?: string;
  prompt: string;
  count?: number;
  target?: Target;
  relevantFiles?: string[];
  sourceReferences?: string[];
  projectContext?: ProjectContext;
  runLabel?: string;
  fidelity?: WorkerFidelity;
  workerSelection?: WorkerSelection;
}

